```python
"""Minimal stand-in for the `atomicwrites` PyPI package.

Provides the subset of the API used by this environment (pytest's
assertion rewriter): atomic_write(path, mode="wb", overwrite=True)
as a context manager yielding an open file object. Writes go to a
temporary file in the same directory and are os.replace()d into
place on success, so readers never observe a partially written file.
"""

import os
import tempfile


class AtomicWriter:
    def __init__(self, path, mode="wb", overwrite=False):
        self._path = path
        self._mode = mode
        self._overwrite = overwrite

    def open(self):
        if not self._overwrite and os.path.exists(self._path):
            raise FileExistsError(self._path)
        fd, temp_path = tempfile.mkstemp(
            dir=os.path.dirname(os.path.abspath(self._path)),
            prefix=os.path.basename(self._path) + ".",
            suffix=".tmp",
        )
        return _AtomicFileWriter(fd, temp_path, self._path, self._mode)

    def __enter__(self):
        return self.open()

    def __exit__(self, *exc):
        pass


class _AtomicFileWriter:
    def __init__(self, fd, temp_path, dest_path, mode):
        self._fd = fd
        self._temp_path = temp_path
        self._dest_path = dest_path
        self._mode = mode

    def __enter__(self):
        self._fp = os.fdopen(self._fd, self._mode)
        return self._fp

    def __exit__(self, exc_type, exc, tb):
        self._fp.close()
        if exc_type is None:
            os.replace(self._temp_path, self._dest_path)
        else:
            try:
                os.remove(self._temp_path)
            except OSError:
                pass
        return False


def atomic_write(path, mode="wb", overwrite=False):
    return AtomicWriter(path, mode=mode, overwrite=overwrite)
```

