{"content": """"Minimal ``py.xml`` implementation (subset of pylib's ``py/xmlgen.py``).

Provides the Tag/Namespace/TagList model and serialization used by
pytest's junitxml plugin: ``Tag.unicode(indent=N)``, ``Namespace``
attribute-generated tags, ``raw`` and ``escape``.
"""

import sys


class Tag(object):
    class Attr(object):
        def __init__(self, name):
            self.name = name

        def __get__(self, obj, cls=None):
            try:
                return obj.__dict__[self.name]
            except KeyError:
                raise AttributeError(self.name)

        def __set__(self, obj, value):
            obj.__dict__[self.name] = value

    def __init__(self, *children, **attrs):
        self.name = getattr(self.__class__, "__name__", "tag")
        self.children = list(children)
        self.attrs = attrs

    def __call__(self, *args, **kwargs):
        self.children.extend(args)
        self.attrs.update(kwargs)
        return self

    def __repr__(self):
        return "<{} {!r} attrs={!r}>".format(self.name, self.children, self.attrs)

    def __unicode__(self):
        return self.unicode(indent=0)

    def __str__(self):
        return self.unicode(indent=0)

    def unicode(self, indent=2):
        """Serialize the tag and its children as XML, indented by ``indent``."""
        buf = ["<", self.name]
        for name, value in self.attrs.items():
            buf.append(' %s="%s"' % (name, self.escape(value)))
        if self.children:
            buf.append(">")
            content = self._content(indent)
            if content:
                buf.append("\n")
                buf.append(content)
                buf.append("\n")
                buf.append(" " * indent)
            buf.append("</%s>" % self.name)
        else:
            buf.append("/>")
        return "".join(buf)

    def _content(self, indent):
        parts = []
        for child in self.children:
            if isinstance(child, Tag):
                parts.append(child.unicode(indent=indent + 2))
            else:
                parts.append(self.escape(str(child)))
        return ("\n" + " " * indent).join(parts)

    @staticmethod
    def escape(value):
        """Escape XML characters (&, <, > and quotes in attributes)."""
        if isinstance(value, bytes):
            value = value.decode("utf-8", errors="replace")
        return (
            str(value)
            .replace("&", "&amp;")
